// Só dias úteis. Rodando à tarde (18h; era 16h50 até 27/10): desde 18h do dia útil ANTERIOR até agora (segunda: desde sexta 18h),
// para não perder o que foi escrito depois do resumo de ontem. Rodando de manhã: ONTEM inteiro (segunda = sexta + sábado + domingo).
// Horário de Brasília (UTC-3). Para trocar a conta que lê os chats: troque a credencial dos nós "Chat - ..." (só eles usam o Chat).
const agoraSP = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const fmt = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const br = s => s.split('-').reverse().join('/');
const tarde = agoraSP.getHours() >= 12;
const fim = new Date(agoraSP); if (!tarde) fim.setDate(fim.getDate() - 1);
const inicio = new Date(agoraSP); inicio.setDate(inicio.getDate() - (agoraSP.getDay() === 1 ? 3 : 1));
const diaIni = fmt(inicio), diaFim = fmt(fim);
// Transição 28/10: o resumo de 27/10 cortou em 16h50, então o de 28/10 começa em 16h50.
const corte = diaIni <= '2026-10-27' ? { utc: 'T19:50:00Z', txt: '16h50' } : { utc: 'T21:00:00Z', txt: '18h' };
let dia, diaBr, de, ate;
if (tarde) {
  dia = diaFim; diaBr = br(diaFim) + ' (desde ' + br(diaIni) + ' ' + corte.txt + ')';
  de = diaIni + corte.utc;
  ate = new Date().toISOString().replace(/\.\d{3}/, '');
} else {
  dia = diaIni === diaFim ? diaFim : diaIni + ' a ' + diaFim;
  diaBr = diaIni === diaFim ? br(diaFim) : br(diaIni) + ' a ' + br(diaFim);
  de = diaIni + 'T03:00:00Z';
  ate = new Date(new Date(diaFim + 'T03:00:00Z').getTime() + 86400000).toISOString().replace('.000', '');
}
return [{ json: { dia, diaBr, de, ate, pastaNome: 'Zezinho' } }];

// Lê espaços (SPACE) e grupos (GROUP_CHAT). Conversas 1 a 1 (DIRECT_MESSAGE) ficam de fora.
// PRIVACIDADE: o resumo vira o relatório do REDACTED | Geral, então espaços RESTRITOS também ficam de fora
// (descrição com "acesso restrito"/"interface restrita", nome com "Interno" ou "DP & RH"), e o espaço de teste do TI.
// Cuidado: o Geral diz "não publicar informações restritas" e NÃO é restrito.
const c = $('Config (dia e conta)').first().json;
const RESTRITO = s => /acesso restrito|interface restrita/i.test((s.spaceDetails && s.spaceDetails.description) || '') || /interno|dp & rh|teste agente de ia/i.test(s.displayName || '');
const lista = ($input.first().json.spaces || []).filter(s => s.spaceType !== 'DIRECT_MESSAGE' && s.type !== 'DM' && !RESTRITO(s));
return lista.map(s => ({ json: { space: s.name, nome: s.displayName || '(grupo sem nome)', tipo: s.spaceType || s.type, de: c.de, ate: c.ate } }));

const c = $('Config (dia e conta)').first().json;
const esp = $('Espaços e grupos (sem conversas privadas)').all().map(i => i.json);
const msgs = $('Chat - mensagens do dia').all().map(i => i.json);
const mem = $('Chat - membros (nomes)').all().map(i => i.json);
const hora = iso => new Date(iso).toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
const br = c.diaBr;
let total = 0, partes = [], erros = [];
esp.forEach((e, i) => {
  const r = msgs[i] || {};
  if (r.error) { erros.push(e.nome + ': ' + JSON.stringify(r.error).slice(0, 150)); return; }
  const lista = r.messages || [];
  if (!lista.length) return;
  const nomes = {};
  ((mem[i] || {}).memberships || []).forEach(m => { if (m.member && m.member.name) nomes[m.member.name] = m.member.displayName || ''; });
  let t = '\n==============================\nESPAÇO: ' + e.nome + ' (' + lista.length + ' mensagens)\n==============================\n';
  lista.forEach(m => {
    const s = m.sender || {};
    const autor = s.displayName || nomes[s.name] || s.email || s.name || '?';
    const texto = (m.text || m.formattedText || (m.attachment && m.attachment.length ? '' : '(sem texto)')).trim();
    const anexos = (m.attachment || []).map(a => a.contentName || 'anexo').join(', ');
    t += '[' + hora(m.createTime) + '] ' + (m.threadReply ? '   ↳ ' : '') + autor + (s.type === 'BOT' ? ' (robô)' : '') + ': ' + texto + (anexos ? ' [anexo: ' + anexos + ']' : '') + '\n';
  });
  total += lista.length; partes.push(t);
});
let doc = 'RESUMO DOS CHATS DA REDACTED — ' + br + '\n';
doc += 'Gerado automaticamente pelo n8n para o Zezinho. Conteúdo: todas as mensagens do período em espaços e grupos do Google Chat (conversas privadas 1 a 1 não entram). Na segunda, o resumo junta sexta, sábado e domingo.\n';
doc += 'Espaços lidos: ' + esp.length + ' — com mensagens no período: ' + partes.length + ' — total de mensagens: ' + total + '\n';
doc += '"↳" = resposta dentro de uma conversa (thread).\n';
if (erros.length) doc += '\nNÃO FOI POSSÍVEL LER: ' + erros.join(' | ') + '\n';
if (!partes.length) doc += '\nNenhuma mensagem nos chats neste período.\n';
doc += partes.join('');
return [{ json: { dia: c.dia, nomeArquivo: 'Chats REDACTED — ' + c.dia, texto: doc, total, espacos: esp.length, comMensagens: partes.length, erros } }];
